<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import data from '../data/retrieval-regression.json'

const category = ref(''), failuresOnly = ref(false), selected = ref(data.rows[0]!.id)
const rows = computed(() => data.rows.filter(row => (!category.value || row.category === category.value) && (!failuresOnly.value || !row.assessment.passed)))
const current = computed(() => rows.value.find(row => row.id === selected.value))
watch(rows, items => { if (!items.some(row => row.id === selected.value)) selected.value = items[0]?.id ?? '' })
const statuses: Record<string, string> = { supported: '有检索结果', evidence_conflict: '证据冲突', no_applicable_evidence: '无适用证据', no_lexical_match: '无词项匹配', low_relevance: '弱相关' }
const extraChunks = data.rows.reduce((total, row) => total + row.assessment.extra_chunks, 0)
</script>

<template>
  <section class="retrieval-regression" aria-label="离线检索回归结果">
    <div class="retrieval-metrics"><div><small>机械回归检查</small><strong>{{ data.metrics.passed }} / {{ data.metrics.total }}</strong></div><div><small>宏平均Recall@3 · {{ data.metrics.positive_queries }} 条查询</small><strong>{{ data.metrics.macro_recall_at_3.toFixed(2) }}</strong></div><div><small>无答案误召回</small><strong>{{ data.metrics.no_answer_wrong_retrieval }} / {{ data.metrics.no_answer_queries }}</strong></div><div><small>额外非预期条款</small><strong>{{ extraChunks }} 条</strong></div></div>
    <div class="retrieval-filters"><label>检索分组<select v-model="category" aria-label="检索分组"><option value="">全部分组</option><option v-for="(counts, name) in data.categories" :key="name" :value="name">{{ name }} · {{ counts.passed }}/{{ counts.total }}</option></select></label><label><input v-model="failuresOnly" type="checkbox" />只看未满足检查</label></div>
    <div class="retrieval-layout"><nav class="retrieval-queries" aria-label="检索问题列表"><button v-for="row in rows" :key="row.id" :aria-pressed="current?.id === row.id" @click="selected = row.id"><span>{{ row.id }} · {{ row.category }}</span><strong>{{ row.query }}</strong><small v-if="!row.assessment.passed">检查未满足</small></button></nav>
      <article v-if="current" :key="current.id" class="retrieval-detail" aria-label="检索问题详情"><h3>{{ current.query }}</h3><dl><dt>预期状态</dt><dd>{{ current.expected_statuses.map(value => statuses[value] ?? value).join(' / ') }}</dd><dt>实际状态</dt><dd>{{ statuses[current.observed.status] ?? current.observed.status }}</dd><dt>本例检查</dt><dd>{{ current.assessment.passed ? '满足冻结预期' : current.assessment.issues.join(' / ') }}</dd></dl>
        <section><h4>预期证据</h4><p v-if="!current.expected_chunks.length">无预期条款</p><blockquote v-for="chunk in current.expected_chunks" :key="chunk.document_id">{{ chunk.text }}</blockquote></section>
        <section><h4>实际召回 · {{ current.observed.chunks.length }} 条</h4><p v-if="!current.observed.chunks.length">没有返回条款</p><div v-for="(chunk, index) in current.observed.chunks" :key="chunk.chunk_id" class="retrieval-chunk"><small>第{{ index + 1 }}条 · BM25 {{ chunk.score }}</small><blockquote>{{ chunk.text }}</blockquote></div></section>
        <details><summary>词项、分母与原始检索返回</summary><p>BM25分数用于当前索引内排序，不代表可信概率。额外非预期条款逐项保留，不由命中一个正确条款推断整段回答正确。</p><pre tabindex="0">{{ JSON.stringify({ reference_clock: current.reference_clock, query_tokens: 'query_tokens' in current.observed ? current.observed.query_tokens : null, assessment: current.assessment, observed: current.observed }, null, 2) }}</pre></details>
      </article><p v-else class="retrieval-empty" role="status">当前筛选没有问题。</p></div>
    <details class="retrieval-provenance"><summary>冻结协议、来源SHA与适用范围</summary><p>{{ data.boundary }}</p><p>只读保存结果，不重新检索或调用模型。宏平均Recall@3仅统计{{ data.metrics.positive_queries }}条有预期证据的查询；{{ extraChunks }}条额外非预期条款单列，不当作回答正确。</p><p>{{ data.storage }}。检索使用原应用分词、BM25和适用性过滤；未连接平台主库或Redis，不是MySQL集成测试。</p><pre tabindex="0">{{ JSON.stringify(data.source, null, 2) }}</pre></details>
  </section>
</template>

