.retrieval-layout { display:grid; grid-template-columns:270px minmax(0,1fr); gap:18px; align-items:start; }.retrieval-queries { display:grid; max-height:660px; overflow:auto; border:1px solid var(--ac-border); border-radius:10px; background:var(--el-bg-color); }.retrieval-queries button { border:0; border-left:3px solid transparent; padding:16px; background:transparent; text-align:left; cursor:pointer; color:var(--ac-text); transition:background .16s,border-color .16s; }.retrieval-queries button:hover { background:var(--ac-accent-soft); border-left-color:var(--ac-accent); }.retrieval-queries button:active { background:var(--ac-surface-soft); }.retrieval-queries button+button { border-top:1px solid var(--ac-border); }.retrieval-queries button[aria-pressed=true] { border-left-color:var(--ac-accent); background:var(--ac-accent-soft); }.retrieval-queries span,.retrieval-queries small { display:block; font-size:12px; color:var(--ac-muted); }.retrieval-queries strong { display:block; font-size:14px; line-height:1.8; margin:6px 0; font-weight:500; color:var(--ac-ink); }
.retrieval-detail { animation:research-detail .18s ease-out; padding:24px; border:1px solid var(--ac-border); border-radius:10px; background:var(--el-bg-color); min-width:0; color:var(--ac-text); }.retrieval-detail h3 { font-size:18px; color:var(--ac-ink); margin:0; }.retrieval-detail dl { display:grid; grid-template-columns:90px minmax(0,1fr); gap:10px; font-size:13px; }.retrieval-detail dd { margin:0; }.retrieval-detail dt { color:var(--ac-muted); }.retrieval-detail section { border-top:1px solid var(--ac-border); margin-top:20px; padding-top:18px; }.retrieval-detail h4 { font-size:14px; margin:0 0 10px; color:var(--ac-ink); }.retrieval-detail p,.retrieval-provenance p { font-size:13px; line-height:1.9; }.retrieval-detail blockquote { margin:10px 0; padding:12px; background:var(--ac-surface-soft); border-left:3px solid var(--ac-border-hover); white-space:pre-wrap; font-size:13px; line-height:1.9; }.retrieval-chunk { margin:16px 0; }.retrieval-chunk small { font-size:12px; color:var(--ac-muted); }
details { margin-top:20px; font-size:12px; color:var(--ac-muted); }summary { cursor:pointer; }pre { max-height:400px; overflow:auto; white-space:pre-wrap; overflow-wrap:anywhere; font:12px/1.8 var(--ac-mono); background:var(--ac-surface-soft); padding:14px; border-radius:6px; }.retrieval-empty { font-size:13px; line-height:1.9; color:var(--ac-muted); padding:24px; }
