@media(max-width:700px) { .retrieval-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); padding:0; }.retrieval-metrics>div { padding:14px; }.retrieval-metrics>div+div { border-left:0; }.retrieval-metrics>div:nth-child(even) { border-left:1px solid var(--ac-border); }.retrieval-metrics>div:nth-child(n+3) { border-top:1px solid var(--ac-border); }.retrieval-metrics strong { font-size:24px; }.retrieval-layout { grid-template-columns:1fr; }.retrieval-queries { max-height:260px; }.retrieval-queries button { padding:12px; }.retrieval-filters>label:first-child { width:100%; }.retrieval-filters select { width:100%; }.retrieval-detail h3 { font-size:17px; } }
@media(prefers-reduced-motion:reduce) { .retrieval-detail { animation:none; }.retrieval-queries button { transition:none; } }
</style>
